(() => {
 'use strict';
 const D=globalThis.ROOK_DATA, M=globalThis.RookMetrics, S=globalThis.ROOK_SUPPORT;
 let lang=/^es/i.test(navigator.language)?'es':'en';try{lang=localStorage.getItem('rook-language')||lang;}catch{}
 const state={lang,view:'overview',start:'2026-06-29',end:'2026-09-06',preset:'matched',selected:D?.responders.slice()||[],search:'',week:'',sort:'delta',detail:null,menu:false};
 const L=(en,es)=>state.lang==='es'?es:en, esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const num=(v,n=0)=>v===null||!Number.isFinite(v)?L('Not applicable','No aplica'):new Intl.NumberFormat(state.lang==='es'?'es-ES':'en-US',{minimumFractionDigits:n,maximumFractionDigits:n}).format(v);
 const pct=v=>v===null?L('Not applicable','No aplica'):num(v,2)+(state.lang==='es'?' %':'%');
 const date=v=>!v?L('Data unavailable','Datos no disponibles'):new Intl.DateTimeFormat(state.lang==='es'?'es-ES':'en-GB',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(v+'T12:00:00Z'));
 const add=(d,n)=>new Date(Date.parse(d+'T00:00:00Z')+n*86400000).toISOString().slice(0,10);
 const range=r=>M.daysInRange(r)?`${date(r.start)} – ${date(r.end)} · ${M.daysInRange(r)} ${L('days','días')}`:L('No overlapping dates','Sin fechas coincidentes');
 const labels=()=>({overview:L('Overview','Resumen'),responders:L('Responders','Respondedores'),evidence:L('Evidence','Evidencia'),research:L('Tickets vs pings','Tickets y pings'),method:L('Method & sources','Método y fuentes')});
 const help=()=>L('A ping is an offer to one responder. Accepted means taken; explicitly declined means turned down; missed means no response within the time limit. One callout may generate several pings.','Un ping es una oferta a un respondedor. Taken significa aceptada; turned down, rechazada explícitamente; missed, sin respuesta dentro del plazo. Un incidente puede generar varios pings.');
 const panel=(title,sub,body,extra='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2><p>${sub}</p></div>${extra}</div><div class="panel-body">${body}</div></section>`;
 const table=(heads,body,cls='')=>`<div class="table-wrap"><table class="${cls}"><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`;
 const cell=v=>`<td class="number">${v}</td>`;
 function model(){
  const requested={start:state.start,end:state.end},clipped=M.clipRange(requested,D.coverage),valid=M.daysInRange(clipped)>0;
  const events=valid&&state.selected.length?M.selectEvents(D.events,{...clipped,responders:state.selected}):[];
  const preset=M.presets[state.preset],before=M.clipRange(preset.before,clipped),after=M.clipRange(preset.after,clipped);
  const comparison=M.compare(events,before,after);
  return {requested,clipped,valid,events,before,after,...comparison,weeks:M.summarizeWeeks(events),rows:M.weeklyRows(events),outOfCoverage:state.start<D.coverage.start||state.end>D.coverage.end};
 }
 // Range objects and totals deliberately use separate names.
 function dataModel(){const a=model(),preset=M.presets[state.preset];a.beforeRange=M.clipRange(preset.before,a.clipped);a.afterRange=M.clipRange(preset.after,a.clipped);return a;}
 function heading(){return `<div class="page-heading"><div><div class="eyebrow">DISPATCH / ${L('RELEASE 4.2 REVIEW','REVISIÓN DE RELEASE 4.2')}</div><h1>${({overview:L('See what changed.','Entiende qué cambió.'),responders:L('Follow the distribution.','Observa la distribución.'),evidence:L('Every number, traceable.','Cada cifra, verificable.'),research:L('Two sources. One timeline.','Dos fuentes. Una cronología.'),method:L('Know what the data says.','Conoce el alcance de los datos.')})[state.view]}</h1><p>${L('Acceptance, unanswered offers and the people behind the aggregate.','Aceptación, ofertas sin respuesta y las personas detrás del promedio.')}</p></div><div class="heading-actions"><button class="button" data-action="view" data-view="method">${L('Read the method','Ver el método')}</button><button class="button primary" data-action="export">↓ ${L('Export evidence','Exportar evidencia')}</button></div></div>`;}
 function filters(){return `<section class="filters" aria-label="${L('Data filters','Filtros de datos')}"><div class="filter"><label for="start">${L('From','Desde')}</label><input type="date" id="start" value="${state.start}"></div><div class="filter"><label for="end">${L('Through','Hasta')}</label><input type="date" id="end" value="${state.end}"></div><div class="filter preset"><label for="preset">${L('Comparison','Comparación')}</label><select id="preset">${[['matched',L('Matched windows · 3 weeks each','Ventanas iguales · 3 semanas')],['date',L('Split at 12 August','Corte al 12 de agosto')],['full',L('All complete weeks · 6 vs 3','Semanas completas · 6 frente a 3')]].map(([v,l])=>`<option value="${v}" ${state.preset===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="filter"><span class="filter-label">${L('Responders','Respondedores')}</span><details class="responders-filter" ${state.menu?'open':''}><summary>${state.selected.length===16?L('All 16 responders','Los 16 respondedores'):num(state.selected.length)+' '+L('selected','seleccionados')} ▾</summary><div class="check-menu"><div class="check-actions"><button data-action="all">${L('Select all','Seleccionar todos')}</button><button data-action="none">${L('Clear selection','Quitar selección')}</button></div>${D.responders.map(r=>`<label><input type="checkbox" data-responder="${esc(r)}" ${state.selected.includes(r)?'checked':''}>${esc(r)}</label>`).join('')}</div></details></div><button class="reset" data-action="reset">${L('Reset filters','Restablecer filtros')}</button></section>`;}
 function notices(m){let out='';if(!state.start||!state.end||state.start>state.end)out+=notice(L('Choose a valid date range. The start must be on or before the end.','Elige un periodo válido. El inicio debe ser anterior o igual al fin.'));else if(m.outOfCoverage)out+=notice(L('Part of your selection is outside the snapshot. Only observed dates are shown; missing dates are not zero activity.','Parte de la selección está fuera de la instantánea. Solo se muestran fechas observadas; los días ausentes no equivalen a cero actividad.'));if(!state.selected.length)out+=notice(L('No responders selected. Choose at least one to see the evidence.','No hay respondedores seleccionados. Elige al menos uno para consultar la evidencia.'));return out;}
 const notice=(s,info=false)=>`<div class="notice ${info?'info':''}" role="status"><span aria-hidden="true">ⓘ</span><p>${s}</p></div>`;
 function periodStrip(m){return `<div class="period-strip"><span class="period-tag"><i class="period-mark"></i><strong>${L('Before','Antes')}</strong> ${range(m.beforeRange)}</span><span aria-hidden="true">→</span><span class="period-tag"><i class="period-mark after"></i><strong>${L('After','Después')}</strong> ${range(m.afterRange)}</span></div>`;}
 function metrics(m){const days1=M.daysInRange(m.beforeRange),days2=M.daysInRange(m.afterRange);const specs=[['acceptance',L('Acceptance rate','Tasa de aceptación'),'taken',false],['missedRate',L('No response in time','Sin respuesta a tiempo'),'missed',true],['declinedRate',L('Explicitly declined','Rechazadas explícitamente'),'turned_down',true],['volume',L('Pings per week','Pings por semana'),'pings',false]];
 return `<div class="metric-grid">${specs.map(([key,label,count,badUp])=>{const b=key==='volume'?(days1?m.before.pings*7/days1:null):m.before[key],a=key==='volume'?(days2?m.after.pings*7/days2:null):m.after[key],delta=a!==null&&b!==null?a-b:null;const deltaText=delta===null?'—':`${delta>0?'+':''}${num(delta,2)} ${key==='volume'?L('pings','pings'):L('pp','pp')}`;return `<article class="metric"><div class="metric-title">${label}<span class="metric-icon" aria-hidden="true">${key==='volume'?'↗':'◉'}</span></div><div class="metric-number">${key==='volume'?num(a,2):pct(a)}</div><div class="metric-count">${L('After','Después')}: ${num(m.after[count])}${key==='volume'?' / '+num(days2)+' '+L('days','días'):' / '+num(m.after.pings)+' pings'}</div><div class="metric-bottom"><span>${L('Before','Antes')}: ${key==='volume'?num(b,2):pct(b)}<br>${num(m.before[count])}${key==='volume'?' / '+num(days1)+' '+L('days','días'):' / '+num(m.before.pings)+' pings'}</span><span class="delta ${key==='volume'||delta===null?'':((badUp?delta>0:delta<0)?'down':'up')}">${deltaText}</span></div></article>`}).join('')}</div>`;}
 function weekTable(m){return table([L('Week of','Semana del'),'Pings',L('Accepted','Aceptadas'),L('Declined','Rechazadas'),L('No response','Sin respuesta'),L('Acceptance','Aceptación')],m.weeks.map(w=>`<tr><td><button class="link-button" data-action="week" data-week="${w.week_start}">${date(w.week_start)}</button>${w.week_start==='2026-08-10'?`<span class="status-chip">${L('TRANSITION','TRANSICIÓN')}</span>`:''}${w.week_start<m.clipped.start||add(w.week_start,6)>m.clipped.end?`<span class="status-chip">${L('PARTIAL','PARCIAL')}</span>`:''}</td>${cell(num(w.pings))}${cell(num(w.taken))}${cell(num(w.turned_down))}${cell(num(w.missed))}${cell(pct(w.acceptance))}</tr>`).join(''));}
 function chart(m){if(!m.weeks.length)return empty();const width=900,height=280,x=i=>55+i*(790/Math.max(1,m.weeks.length-1)),y=v=>25+(100-v)*1.65;const pts=m.weeks.map((w,i)=>`${x(i)},${y(w.acceptance)}`).join(' '),transition=m.weeks.findIndex(w=>w.week_start==='2026-08-10');
 return `<div class="chart"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${L('Weekly acceptance and ping volume. Exact values appear in the table below.','Aceptación y pings por semana. Los valores exactos están en la tabla inferior.')}">${[0,25,50,75,100].map(v=>`<line class="axis-line" x1="48" x2="865" y1="${y(v)}" y2="${y(v)}"/><text x="5" y="${y(v)+4}">${v}%</text>`).join('')}${transition>=0?`<rect x="${x(transition)}" y="14" width="${790/Math.max(1,m.weeks.length-1)}" height="226" fill="#f8eedb"/><line x1="${x(transition)+(790/Math.max(1,m.weeks.length-1))*2/7}" x2="${x(transition)+(790/Math.max(1,m.weeks.length-1))*2/7}" y1="12" y2="240" stroke="#b78a4d" stroke-dasharray="4 4"/><text class="release-label" x="${x(transition)+(790/Math.max(1,m.weeks.length-1))*2/7-12}" y="10">4.2 · 12 ${L('Aug','ago')}</text>`:''}${m.weeks.map((w,i)=>`<rect class="bar" x="${x(i)-12}" width="24" y="${238-w.pings/Math.max(...m.weeks.map(z=>z.pings))*35}" height="${w.pings/Math.max(...m.weeks.map(z=>z.pings))*35}"/><text x="${x(i)}" y="257" text-anchor="middle">${date(w.week_start)}</text>`).join('')}<polyline class="trend-line" points="${pts}"/>${m.weeks.map((w,i)=>`<circle class="trend-dot" cx="${x(i)}" cy="${y(w.acceptance)}" r="4"/><text class="chart-value" x="${x(i)}" y="${y(w.acceptance)-11}" text-anchor="middle">${num(w.acceptance,1)}%</text>`).join('')}</svg></div><div class="chart-note"><span>${L('Weekly points · Monday–Sunday · Bars show relative ping volume','Puntos semanales · lunes–domingo · Barras: volumen relativo de pings')}</span><span>${L('12 August falls inside the transition week.','El 12 de agosto está dentro de la semana de transición.')}</span></div>`;}
 function empty(){return `<div class="empty"><div class="empty-icon">∅</div><h2>${L('No data in this selection','Sin datos en esta selección')}</h2><p>${L('Check the dates and responders. Data outside 29 June–6 September is unavailable.','Revisa fechas y respondedores. No hay datos fuera del 29 de junio–6 de septiembre.')}</p><button class="button" data-action="reset">${L('Reset filters','Restablecer filtros')}</button></div>`;}
 function overview(m){const cohort=['Farlight','Meteor Mite','The Undertow','Vesper'].filter(r=>state.selected.includes(r)),a=cohort.length?M.compare(m.events,m.beforeRange,m.afterRange,cohort):{before:{pings:0},after:{pings:0}};return periodStrip(m)+metrics(m)+panel(L('Acceptance over time','Aceptación a lo largo del tiempo'),L('All observed weeks in the selected range, including the transition week.','Todas las semanas observadas del periodo, incluida la transición.'),chart(m))+`<details class="panel table-toggle"><summary>${L('View weekly numbers','Ver cifras semanales')}</summary>${weekTable(m)}</details><div class="split">${panel(L('Averages can hide a quieter phone.','Los promedios pueden ocultar un teléfono silencioso.'),L('An observed cohort to investigate, not a causal explanation.','Una cohorte observada para investigar, no una explicación causal.'),`<div class="insight"><div class="big">${num(a.before.pings)} → ${num(a.after.pings)} <small>pings</small></div><p class="aliases">${cohort.map(esc).join(' · ')||L('No cohort members selected','Ningún miembro de la cohorte seleccionado')}</p><p>${L('These four responders received very few offers by the end of August. Their history, availability and eligibility still need verification. Figures follow the selected comparison.','Estos cuatro respondedores recibían muy pocas ofertas a finales de agosto. Falta verificar historial, disponibilidad y elegibilidad. Las cifras siguen la comparación seleccionada.')}</p><button class="button" data-action="view" data-view="responders">${L('Explore every responder','Explorar todos los respondedores')} →</button></div>`)}${panel(L('What this can tell us','Qué podemos concluir'),L('Observed change ≠ established cause','Cambio observado ≠ causa establecida'),`<ul class="method-list body-copy"><li>${L('Acceptance and unanswered offers changed around 4.2.','La aceptación y las ofertas sin respuesta cambiaron alrededor de 4.2.')}</li><li>${L('Routing weights and the response window changed together.','Los pesos de routing y el plazo de respuesta cambiaron juntos.')}</li><li>${L('A missed ping does not prove a failed notification.','Un ping sin respuesta no demuestra un fallo de notificación.')}</li><li>${L('No ticket does not mean no impact.','Que no haya ticket no significa que no haya impacto.')}</li></ul>`)}</div>`;}
 function distribution(m){let rows=state.selected.length?M.distribution(D.events,m.beforeRange,m.afterRange,state.selected):[];rows.sort(state.sort==='name'?(a,b)=>a.responder.localeCompare(b.responder):(a,b)=>(a.delta??0)-(b.delta??0));return periodStrip(m)+panel(L('Who received the offers?','¿Quién recibió las ofertas?'),L('Counts and rates use the selected comparison. Select an alias for its weekly detail.','Conteos y tasas de la comparación seleccionada. Abre un alias para ver su detalle semanal.'),table([L('Responder','Respondedor'),L('Pings/week before','Pings/sem. antes'),L('Pings/week after','Pings/sem. después'),L('Change','Cambio'),L('Share before → after','Participación antes → después'),L('Accepted after','Aceptadas después')],rows.filter(r=>r.responder.toLowerCase().includes(state.search.toLowerCase())).map(r=>`<tr><td><button class="link-button" data-action="detail" data-name="${esc(r.responder)}">${esc(r.responder)}</button></td>${cell(num(r.beforePerWeek,2))}${cell(num(r.afterPerWeek,2))}${cell((r.delta>0?'+':'')+num(r.delta,2)+'<br><small>'+pct(r.deltaPct)+'</small>')}${cell(pct(r.shareBefore)+' → '+pct(r.shareAfter))}${cell(`${r.after.taken}/${r.after.pings}<br><small>${pct(r.after.acceptance)}</small>`)}</tr>`).join('')),`<div class="table-tools"><label>${L('Search','Buscar')} <input id="search" class="search" value="${esc(state.search)}"></label><select id="sort" class="sort-select" aria-label="${L('Sort responders','Ordenar respondedores')}"><option value="delta">${L('Largest declines first','Mayores descensos primero')}</option><option value="name" ${state.sort==='name'?'selected':''}>${L('Name','Nombre')}</option></select></div>`)+heatmap(m);}
 function heatmap(m){const weeks=[];if(m.valid)for(let w=M.weekStart(m.clipped.start);w<=m.clipped.end;w=add(w,7))weeks.push(w);const lookup=new Map(m.rows.map(r=>[r.responder+'|'+r.week_start,r]));return panel(L('Weekly offer distribution','Distribución semanal de ofertas'),L('Dashed zero = no recorded pings in this covered cell; it does not prove availability.','Cero punteado = sin pings registrados en esa celda cubierta; no demuestra disponibilidad.'),table([L('Responder','Respondedor'),...weeks.map(w=>date(w)+(w==='2026-08-10'?' *':''))],state.selected.map(r=>`<tr><td>${esc(r)}</td>${weeks.map(w=>{const row=lookup.get(r+'|'+w),n=row?.pings||0;return `<td class="${w==='2026-08-10'?'transition-col':''}"><span class="heat-cell ${n===0?'zero':n>13?'dense':''}" style="--opacity:${Math.min(.85,.1+n*.032)}" title="${esc(r)} · ${date(w)}: ${n} pings; ${L('acceptance','aceptación')} ${pct(row?.acceptance??null)}${!row?' · '+L('derived zero','cero derivado'):''}">${n}</span></td>`}).join('')}</tr>`).join(''),'heatmap')+`<p class="body-copy mt">* ${L('Transition week. Partial date selections count only included days. With zero pings, acceptance is not applicable.','Semana de transición. Las selecciones parciales cuentan solo los días incluidos. Con cero pings, la aceptación no aplica.')}</p>`);}
 function evidenceRows(m){return m.rows.filter(r=>(!state.week||r.week_start===state.week)&&r.responder.toLowerCase().includes(state.search.toLowerCase()));}
 function evidence(m){const rows=evidenceRows(m),pings=rows.reduce((n,r)=>n+r.pings,0);return panel(L('The rows behind the numbers','Las filas detrás de las cifras'),`${num(rows.length)} ${L('observed responder-week rows','filas observadas de respondedor-semana')} · ${num(pings)} pings`,table([L('Week','Semana'),L('Responder','Respondedor'),'Pings',L('Accepted','Aceptadas'),L('Declined','Rechazadas'),L('No response','Sin respuesta'),L('Acceptance','Aceptación')],rows.map(r=>`<tr><td>${date(r.week_start)}</td><td>${esc(r.responder)}</td>${cell(r.pings)}${cell(r.taken)}${cell(r.turned_down)}${cell(r.missed)}${cell(pct(r.acceptance))}</tr>`).join(''))+`<p class="body-copy mt">${L('Observed rows only. The derived zero cell for Farlight is not an original source row. Counts for partial weeks include selected days only.','Solo filas observadas. La celda derivada de cero de Farlight no es una fila original. Las semanas parciales incluyen únicamente los días seleccionados.')}</p>`,`<div class="table-tools"><label>${L('Search alias','Buscar alias')}<input class="search" id="search" value="${esc(state.search)}"></label><label>${L('Week drill-down','Detalle por semana')} <select id="week" class="week-select"><option value="">${L('All weeks','Todas las semanas')}</option>${m.weeks.map(w=>`<option value="${w.week_start}" ${state.week===w.week_start?'selected':''}>${date(w.week_start)}</option>`).join('')}</select></label></div>`)+`<div class="heading-actions"><button class="button primary" data-action="export">↓ ${L('Export these rows','Exportar estas filas')}</button><button class="button" data-action="metadata">${L('Download method & dictionary','Descargar método y diccionario')}</button><a class="button" href="source-rows.csv" download>${L('Original 159-row CSV','CSV original de 159 filas')}</a></div>`;}
 function method(){return notice(L('Historical snapshot, not a live operations feed. Data extraction: 3 Nov 2026. Source coverage: 29 Jun–6 Sep 2026. Source completeness and exact local timezone are unconfirmed.','Instantánea histórica, no un seguimiento en vivo. Extracción: 3 nov 2026. Cobertura: 29 jun–6 sep 2026. La completitud de origen y la zona local exacta están pendientes de confirmar.'),true)+`<div class="method-grid">${panel(L('Definitions that stay consistent','Definiciones consistentes'),L('Every percentage includes its denominator.','Cada porcentaje incluye su denominador.'),`<dl class="definition-list"><div><dt>${L('Pings and outcomes','Pings y resultados')}</dt><dd>${help()}</dd></div><div><dt>${L('Acceptance rate','Tasa de aceptación')}</dt><dd>${L('Total accepted ÷ total pings. Never an unweighted average of responder rates.','Total de aceptadas ÷ total de pings. Nunca un promedio simple de tasas individuales.')}</dd></div><div><dt>${L('Pings per week','Pings por semana')}</dt><dd>${L('Total × 7 ÷ included calendar days. Compare unequal periods using rates, not raw totals.','Total × 7 ÷ días calendario incluidos. Compara periodos desiguales mediante tasas, no totales brutos.')}</dd></div><div><dt>${L('Zeros and missing data','Ceros y datos ausentes')}</dt><dd>${L('Zero offers in a covered interval is distinct from unavailable data. Zero pings means acceptance is not applicable.','Cero ofertas en un intervalo cubierto es distinto de datos no disponibles. Con cero pings, la aceptación no aplica.')}</dd></div></dl>`)}${panel(L('Comparison choices','Opciones de comparación'),L('Different windows answer different questions.','Ventanas diferentes responden preguntas diferentes.'),`<ul class="method-list body-copy"><li>${L('Matched: 20 Jul–9 Aug vs 17 Aug–6 Sep (21 days each).','Iguales: 20 jul–9 ago frente a 17 ago–6 sep (21 días cada una).')}</li><li>${L('Date split: 29 Jun–11 Aug vs 12 Aug–6 Sep. Midnight on 12 Aug is a stated assumption, not the verified deployment time.','Corte por fecha: 29 jun–11 ago frente a 12 ago–6 sep. Medianoche del 12 ago es un supuesto, no la hora verificada de despliegue.')}</li><li>${L('Complete weeks: six baseline vs three later weeks. The week of 10 Aug is excluded from this comparison.','Semanas completas: seis previas frente a tres posteriores. Se excluye la semana del 10 ago de esta comparación.')}</li><li>${L('The date filter clips both comparison windows. Weekly charts and evidence include all dates selected, including transition dates excluded by a comparison preset.','El filtro de fechas recorta ambas ventanas. El gráfico y la evidencia incluyen todas las fechas seleccionadas, incluidas las de transición excluidas por un preset.')}</li></ul>`)}</div>`+panel(L('What remains unknown','Qué falta conocer'),L('These values cannot be inferred from the available columns.','Estos valores no se pueden inferir de las columnas disponibles.'),`<ul class="method-list body-copy"><li>${L('Notification delivery, display time and time-to-accept.','Entrega de notificaciones, tiempo visible y tiempo hasta aceptar.')}</li><li>${L('Historical availability, eligibility, capabilities and routing scores.','Disponibilidad histórica, elegibilidad, capacidades y scores de routing.')}</li><li>${L('Coverage gaps, causality of the release and sustained recovery.','Brechas de cobertura, causalidad del lanzamiento y recuperación sostenida.')}</li><li>${L('Operational changes and team sign-off remain pending. This dashboard is read-only.','Los cambios operativos y el acuerdo del equipo están pendientes. El dashboard es de consulta.')}</li></ul>`)+panel(L('Source query','Consulta fuente'),L('Event data enables date-level comparisons; weekly exports alone do not.','Los eventos permiten comparar por fecha; el CSV semanal por sí solo no.'),`<pre class="code">SELECT date_trunc('week', sent_at)::date AS week_start,
       responder, COUNT(*) AS pings,
       COUNT(*) FILTER (WHERE outcome = 'taken') AS taken,
       COUNT(*) FILTER (WHERE outcome = 'turned down') AS turned_down,
       COUNT(*) FILTER (WHERE outcome = 'missed') AS missed
FROM rook.pings
WHERE sent_at &gt;= TIMESTAMP '2026-06-01'
GROUP BY 1, 2 ORDER BY 1, 2;</pre>`)+downloads();}
 function downloads(){return panel(L('Evidence library','Biblioteca de evidencia'),L('Working documents and source material retain their original language.','Los documentos de trabajo y las fuentes conservan su idioma original.'),`<div class="download-grid">${[['prd-dashboard-dispatch.md','Product requirements','Requisitos del producto'],['investigacion-4-2.md','Investigation & intervention proposal','Investigación y propuesta de intervención'],['validacion-datos.md','Data validation & SQL','Validación de datos y SQL'],['cruce-tickets-pings.md','Ticket classification and evidence','Clasificación y evidencia de tickets'],['tickets-vs-pings-timeline.md','Timing and agreement analysis','Análisis de cronología y concordancia']].map(([f,en,es])=>`<a class="download-card" href="docs/${f}" download><span>${L(en,es)}<small>Markdown · ${L('original document','documento original')}</small></span>↓</a>`).join('')}</div>`);}
 function research(m){const selectedTickets=S.tickets.filter(t=>t.filed_at.slice(0,10)>=state.start&&t.filed_at.slice(0,10)<=state.end&&state.selected.includes(t.about_responder));const weekly={};for(const t of selectedTickets){const w=M.weekStart(t.filed_at);weekly[w]??={all:0,quiet:0,gone:0};weekly[w].all++;weekly[w].quiet+=S.quiet.includes(t.ticket_number);weekly[w].gone+=S.gone.includes(t.ticket_number);}const allWeeks=[...new Set([...m.weeks.map(w=>w.week_start),...Object.keys(weekly)])].sort();const cohort=['Farlight','Meteor Mite','The Undertow','Vesper'];const pings=M.summarizeWeeks(m.events.filter(e=>cohort.includes(e.responder)));const titles=[L('Quiet / less work','Silencio / menos trabajo'),L('Offer moved on','La oferta avanzó'),L('Late / absent notification','Notificación tardía / ausente')],lists=[S.quiet,S.gone,S.delivery];return notice(L('Tickets use filing dates, not verified incident dates. Their coverage ends 7 Sep; ping coverage ends 6 Sep. Filters apply to aliases and dates in both sources. Categories overlap.','Los tickets usan fechas de presentación, no fechas verificadas del incidente. Llegan hasta el 7 sep; los pings, hasta el 6 sep. Los filtros afectan alias y fechas de ambas fuentes. Las categorías se solapan.'),true)+`<div class="research-grid">${lists.map((ids,i)=>`<article class="research-stat"><strong>${selectedTickets.filter(t=>ids.includes(t.ticket_number)).length}</strong><h3>${titles[i]}</h3><p>${L('Matching tickets in the current selection','Tickets coincidentes en la selección actual')}</p></article>`).join('')}</div>`+panel(L('Do the two sources agree?','¿Coinciden las dos fuentes?'),L('Broadly yes; not every literal account matches.','En términos generales sí; no todos los relatos coinciden literalmente.'),`<p class="body-copy">${L('Acceptance changes sharply on 12 Aug (11/25 accepted; 7/25 missed), alongside ticket #3041 about an offer moving on. Quiet-workload reports begin 17 Aug (#3060). In that first full later week the four most affected responders receive 16 pings, then 6 and 3 in subsequent weeks.','La aceptación cambia marcadamente el 12 ago (11/25 aceptadas; 7/25 sin respuesta), junto al ticket #3041 sobre una oferta que avanzó. Las quejas de poco trabajo comienzan el 17 ago (#3060). En esa primera semana completa posterior, los cuatro más afectados reciben 16 pings, luego 6 y 3.')}</p><p class="body-copy">${L('These are findings for the full historical snapshot; the table below follows your filters. Meteor Mite and Vesper have no tickets despite steep declines. Older examples exist: #3014 on 14 Jul (signal loss) and #3034 on 4 Aug (older phone).','Estos hallazgos corresponden a la instantánea completa; la tabla inferior sigue tus filtros. Meteor Mite y Vesper no tienen tickets pese a fuertes descensos. Existen antecedentes: #3014 del 14 jul (sin señal) y #3034 del 4 ago (teléfono antiguo).')}</p>`)+panel(L('Align the clocks','Alinear las fechas'),L('All-topic ticket volume is context, not a Dispatch failure rate.','Los tickets de todos los temas son contexto, no una tasa de fallos de Dispatch.'),table([L('Week of','Semana del'),L('Acceptance','Aceptación'),L('No response','Sin respuesta'),L('Four-responder pings','Pings de los cuatro'),L('All tickets','Todos los tickets'),L('Quiet','Silencio'),L('Moved on','Avanzó')],allWeeks.map(w=>{const p=m.weeks.find(x=>x.week_start===w),t=weekly[w]||{all:0,quiet:0,gone:0},c=pings.find(x=>x.week_start===w);return `<tr><td>${date(w)}${w==='2026-08-10'?' *':''}</td>${cell(p?pct(p.acceptance):'—')}${cell(p?`${p.missed}/${p.pings}`:'—')}${cell(p?num(c?.pings||0):'—')}${cell(t.all)}${cell(t.quiet)}${cell(t.gone)}</tr>`}).join(''))+`<p class="body-copy mt">${L('The four-responder group is Farlight, Meteor Mite, The Undertow and Vesper, restricted to your alias selection. * Transition week.','El grupo incluye Farlight, Meteor Mite, The Undertow y Vesper, limitado a tu selección de alias. * Semana de transición.')}</p>`)+panel(L('Check the claims against the records','Contrastar relatos y registros'),L('Timestamp-relative windows, using the source’s local times.','Ventanas relativas al timestamp, usando la hora local de origen.'),`<ul class="method-list body-copy"><li><strong>#3073 · The Undertow:</strong> ${L('6 pings reported in seven days; 6 recorded.','6 pings reportados en siete días; 6 registrados.')}</li><li><strong>#3086 · Halfmoon:</strong> ${L('8 reported; 8 recorded.','8 reportados; 8 registrados.')}</li><li><strong>#3060 · Farlight:</strong> ${L('“Nothing in three days”; two pings in the preceding 72 hours, including one taken.','«Nada en tres días»; dos pings en las 72 horas anteriores, incluida una aceptación.')}</li><li><strong>#3070 · Corporal Ashgrove:</strong> ${L('Same three-day claim; two recorded, including one taken. Wording may be approximate; clarify rather than dismiss the wider decline.','Mismo relato de tres días; dos registrados, incluida una aceptación. El lenguaje puede ser aproximado; aclarar sin descartar la caída general.')}</li></ul>`)+panel(L('Original ticket evidence','Evidencia original de tickets'),L('Untranslated source text. Open a ticket to read the complete account.','Texto original sin traducir. Abre un ticket para leer el relato completo.'),selectedTickets.map(t=>`<details class="ticket"><summary><strong>#${t.ticket_number}</strong> · ${date(t.filed_at.slice(0,10))} · ${esc(t.about_responder)} — ${esc(t.subject)}</summary><p class="body-copy" lang="en">${esc(t.body)}</p></details>`).join('')||empty());}
 function detail(m){if(!state.detail)return '';const events=m.events.filter(e=>e.responder===state.detail),inner={...m,events,weeks:M.summarizeWeeks(events)},s=M.summary(events);return `<div class="drawer-backdrop"><aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="detail-title"><div class="drawer-title"><div><div class="eyebrow">${L('RESPONDER DETAIL','DETALLE DEL RESPONDEDOR')}</div><h2 id="detail-title">${esc(state.detail)}</h2></div><button class="drawer-close" data-action="close" aria-label="${L('Close detail','Cerrar detalle')}">×</button></div><p>${num(s.pings)} pings · ${num(s.taken)} ${L('accepted','aceptadas')} · ${pct(s.acceptance)}</p>${notice(L('Small counts can make individual rates unstable. No offers does not establish unavailability.','Los recuentos pequeños pueden hacer inestables las tasas individuales. No recibir ofertas no demuestra indisponibilidad.'),true)}${weekTable(inner)}<button class="button mt" data-action="close">${L('Back to distribution','Volver a la distribución')}</button></aside></div>`;}
 function render(){
  const focus=document.activeElement?.id,sel=document.activeElement?.selectionStart;document.documentElement.lang=state.lang;document.title=L('Rook · Dispatch Observatory','Rook · Observatorio Dispatch');
  if(!D||!M||!S){document.getElementById('app').innerHTML=`<div class="empty"><h1>${L('Unable to load the snapshot','No se pudo cargar la instantánea')}</h1><p>${L('Please reload to try again. No missing values have been replaced with zero.','Recarga para reintentar. Los valores ausentes no se han sustituido por ceros.')}</p><button onclick="location.reload()">${L('Retry','Reintentar')}</button></div>`;return;}
  const m=dataModel(),names=labels();let body=state.view==='method'?method():state.view==='research'?research(m):!m.valid?empty():state.view==='overview'?overview(m):state.view==='responders'?distribution(m):evidence(m);
  document.getElementById('app').innerHTML=`<a class="skip" href="#content">${L('Skip to content','Saltar al contenido')}</a><div class="shell"><aside class="sidebar"><div class="wordmark"><span class="rook-symbol" aria-hidden="true">♜</span><div>rook<small>INDUSTRIES</small></div></div><div class="workspace-label">${L('WORKSPACE','ESPACIO DE TRABAJO')}</div><nav class="nav" aria-label="${L('Main navigation','Navegación principal')}">${Object.entries(names).map(([v,n],i)=>`<button data-action="view" data-view="${v}" class="${state.view===v?'active':''}" ${state.view===v?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${['◫','▦','≡','⇄','ⓘ'][i]}</span>${n}</button>`).join('')}</nav><div class="side-bottom"><strong><i class="dot"></i> ${L('Historical snapshot','Instantánea histórica')}</strong>29 ${L('Jun','jun')} – 6 ${L('Sep','sep')} 2026<div class="side-footer">${L('Fictional course scenario','Escenario ficticio del curso')}<br>PRODUCT SCHOOL</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Dispatch <span>/</span><strong>${names[state.view]}</strong></div><div class="top-actions"><span class="snapshot-label"><i class="dot"></i>${L('Read-only · 1,696 recorded pings','Solo consulta · 1.696 pings registrados')}</span><div class="language" aria-label="${L('Language','Idioma')}"><button data-action="lang" data-lang="en" aria-pressed="${state.lang==='en'}">English</button><button data-action="lang" data-lang="es" aria-pressed="${state.lang==='es'}">Español</button></div></div></header><div class="content" id="content">${heading()}${filters()}<div class="context"><span>${L('Coverage','Cobertura')}: 29 ${L('Jun','jun')} – 6 ${L('Sep','sep')} 2026 · ${L('Local source time; timezone unconfirmed','Hora local de origen; zona sin confirmar')}</span><span>${L('Extracted 3 Nov 2026 · completeness unconfirmed','Extracción: 3 nov 2026 · completitud sin confirmar')}</span></div>${notices(m)}${body}<footer class="footer"><span>${help()}</span><span>ROOK / ${L('COURSE DATA','DATOS DEL CURSO')}</span></footer></div></main></div>${detail(m)}`;
  if(focus){const el=document.getElementById(focus);if(el){el.focus({preventScroll:true});if(sel!=null&&el.type==='text')el.setSelectionRange(sel,sel);}}
 }
 function saveFile(name,text,type){const url=URL.createObjectURL(new Blob(['\ufeff',text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function exportRows(){const m=dataModel(),rows=state.view==='evidence'?evidenceRows(m):m.rows;const keys=['week_start','responder','pings','taken','turned_down','missed'];const csv=keys.join(',')+'\n'+rows.map(r=>keys.map(k=>'"'+String(r[k]).replace(/"/g,'""')+'"').join(',')).join('\n');saveFile('rook-pings-'+state.start+'-'+state.end+'.csv',csv,'text/csv;charset=utf-8');}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='lang'){state.lang=b.dataset.lang;try{localStorage.setItem('rook-language',state.lang);}catch{}}if(action==='view'){state.view=b.dataset.view;state.search='';state.week='';state.detail=null;}if(action==='reset'){Object.assign(state,{start:D.coverage.start,end:D.coverage.end,preset:'matched',selected:D.responders.slice(),search:'',week:'',detail:null,menu:false});}if(action==='all'){state.selected=D.responders.slice();state.menu=true;}if(action==='none'){state.selected=[];state.menu=true;}if(action==='week'){state.view='evidence';state.week=b.dataset.week;state.search=state.detail||'';state.detail=null;}if(action==='detail')state.detail=b.dataset.name;if(action==='close')state.detail=null;if(action==='export'){exportRows();return;}if(action==='metadata'){saveFile('rook-method-and-dictionary.json',JSON.stringify({source:'rook.pings',coverage:D.coverage,extractedAt:D.extractedAt,filters:{start:state.start,end:state.end,responders:state.selected,evidenceWeek:state.view==='evidence'?state.week:null,search:state.view==='evidence'?state.search:null},week:'Monday–Sunday / lunes–domingo',timezone:'Local, unconfirmed / local, sin confirmar',dateSplitAssumption:'2026-08-12 00:00 local, not verified deployment time',dictionary:{pings:['Offers sent','Ofertas enviadas'],taken:['Accepted','Aceptadas'],turned_down:['Explicitly declined','Rechazadas explícitamente'],missed:['No response within time limit','Sin respuesta dentro del plazo']},acceptance:'sum(taken)/sum(pings)',zeroDenominator:'Not applicable / No aplica'},null,2),'application/json');return;}render();if(action==='detail')document.querySelector('.drawer-close')?.focus();if(action==='view')window.scrollTo(0,0);});
 document.addEventListener('change',e=>{const t=e.target;if(['start','end','preset','week','sort'].includes(t.id)){state[t.id]=t.value;if(t.id==='start'||t.id==='end')state.week='';render();}if(t.dataset.responder){state.selected=t.checked?[...state.selected,t.dataset.responder]:state.selected.filter(r=>r!==t.dataset.responder);state.menu=true;render();}});
 document.addEventListener('input',e=>{if(e.target.id==='search'){state.search=e.target.value;render();}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.detail){state.detail=null;render();}if(e.key==='Tab'&&state.detail){const els=[...document.querySelectorAll('.drawer button,.drawer a,.drawer input')];if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus();}}});
 render();
})();
